// All villages combined
export const allVillages: Village[] = [
  ...category1Villages,
  ...category2Villages,
];

// Helper function to get villages by category
export const getVillagesByCategory = (category: VillageCategory): Village[] => {
  return allVillages.filter((village) => village.category === category);
};

// Helper function to get villages by kabupaten
export const getVillagesByKabupaten = (kabupaten: string): Village[] => {
  return allVillages.filter((village) => village.kabupaten === kabupaten);
};

// Helper function to get villages by kecamatan
export const getVillagesByKecamatan = (kecamatan: string): Village[] => {
  return allVillages.filter((village) => village.kecamatan === kecamatan);
};

